// READ FILE
// The webhook gives us the uploaded file as binary data.
// Turn it into text, then into a list of lines.

const item = items[0];
const fileKey = Object.keys(item.binary)[0];

const buffer = await this.helpers.getBinaryDataBuffer(0, fileKey);
const text = buffer.toString('utf8');

const lines = text.split('\n').filter(line => line.trim() !== '');

return [{
  json: {
    fileName: item.binary[fileKey].fileName,
    lines: lines
  }
}];

// PARSE LINES
// Every line looks like:  [time] [LEVEL] [PART] message

const lines = items[0].json.lines;

const entries = lines.map(line => {
  const bits = line.match(/\[(.+?)\] \[(.+?)\] \[(.+?)\] (.+)/);
  if (!bits) return null;
  return {
    time: bits[1],
    level: bits[2],
    part: bits[3],
    message: bits[4]
  };
}).filter(entry => entry !== null);

// Count how many lines of each level, and of each part.
const levelCount = {};
const partCount = {};

for (const entry of entries) {
  levelCount[entry.level] = (levelCount[entry.level] || 0) + 1;
  partCount[entry.part] = (partCount[entry.part] || 0) + 1;
}

return [{
  json: {
    fileName: items[0].json.fileName,
    total: entries.length,
    levelCount: levelCount,
    partCount: partCount,
    entries: entries
  }
}];

// FIND THREATS
// Each rule has a name, what to look for, how bad it is,
// and its MITRE ATT&CK id (a public list security teams use).

const RULES = [
  { name: 'Brute force',        find: /failed login/i,                  severity: 'medium', mitre: 'T1110' },
  { name: 'Port scan',          find: /port scan/i,                     severity: 'low',    mitre: 'T1046' },
  { name: 'Blocked connection', find: /blocked outbound/i,              severity: 'medium', mitre: 'T1071' },
  { name: 'Odd process',        find: /powershell -enc|unexpected process/i, severity: 'high', mitre: 'T1059' },
  { name: 'Malware',            find: /malware|trojan/i,                severity: 'high',   mitre: 'T1204' },
  { name: 'Data sent out',      find: /sent \d+MB/i,                    severity: 'high',   mitre: 'T1041' },
  { name: 'Privilege misuse',   find: /sudo without permission|elevation of privilege/i, severity: 'high', mitre: 'T1548' },
  { name: 'SQL injection',      find: /'1'='1|drop table|union select/i, severity: 'high',   mitre: 'T1190' },
  { name: 'Monitoring stopped', find: /monitoring service stopped|logs cleared/i, severity: 'high', mitre: 'T1562' }
];

const entries = items[0].json.entries;
const threats = [];

// Check every line against every rule.
for (const entry of entries) {
  for (const rule of RULES) {
    if (rule.find.test(entry.message)) {
      threats.push({
        time: entry.time,
        level: entry.level,
        part: entry.part,
        message: entry.message,
        threat: rule.name,
        severity: rule.severity,
        mitre: rule.mitre
      });
      break;   // one rule per line is enough
    }
  }
}

// Count the threats by how bad they are.
const severityCount = { high: 0, medium: 0, low: 0 };
for (const threat of threats) {
  severityCount[threat.severity]++;
}

return [{
  json: {
    fileName: items[0].json.fileName,
    total: items[0].json.total,
    levelCount: items[0].json.levelCount,
    partCount: items[0].json.partCount,
    threatCount: threats.length,
    severityCount: severityCount,
    threats: threats
  }
}];

// BUILD PROMPT
// Turn the findings into the question we send to the AI.

const data = items[0].json;

// One line per threat, so the AI only sees facts.
const list = data.threats.map(t =>
  `- ${t.time}  ${t.threat} (${t.mitre}, ${t.severity}): ${t.message}`
).join('\n');

const prompt = `You are a security analyst writing the opening of an incident report.

Log file: ${data.fileName}
Lines read: ${data.total}
Threats found: ${data.threatCount} (high ${data.severityCount.high}, medium ${data.severityCount.medium}, low ${data.severityCount.low})

Findings:
${list}

Write 3 to 5 short sentences in plain English, for a manager who is not technical.
Say what happened, what is most urgent, and what to do first.
End with one line on its own: Risk: Low, Risk: Medium, Risk: High or Risk: Critical.

Rules:
- Use only the findings above. Do not invent anything.
- No bullet points, no headings, no markdown.`;

return [{ json: { prompt: prompt } }];

// ASK AI
// Send the prompt to Gemini and hand back its answer.

const response = await this.helpers.httpRequest({
  method: 'POST',
  url: 'https://generativelanguage.googleapis.com/v1beta/models/gemini-3.6-flash:generateContent',
  headers: {
    'x-goog-api-key': $env.GEMINI_API_KEY,
    'content-type': 'application/json'
  },
  body: {
    contents: [{ parts: [{ text: items[0].json.prompt }] }],
    generationConfig: { temperature: 0.1, maxOutputTokens: 2000 }
  },
  json: true,
  timeout: 90000
});

return [{ json: response }];

// MAKE REPORT
// Build the HTML page: AI summary on top, then the numbers, then the table.

// The findings come from the Find Threats node, a few steps back.
const data = $('Find Threats').first().json;

// The AI answer, if it came back. If anything went wrong we carry on without it.
let summary = 'AI summary unavailable.';
try {
  // The answer can come back in several parts. Take the first one with text.
  const parts = items[0].json.candidates[0].content.parts;
  summary = parts.find(part => part.text).text.trim();
} catch (error) {
  // leave the fallback text
}

// One table row per threat.
const rows = data.threats.map(t => `
    <tr>
      <td>${t.time}</td>
      <td>${t.threat}</td>
      <td><span class="pill ${t.severity}">${t.severity}</span></td>
      <td>${t.mitre}</td>
      <td>${t.message}</td>
    </tr>`).join('');

const html = `<!doctype html>
<html>
<head>
  <meta charset="utf-8">
  <title>Log Analysis Report</title>
  <style>
    body    { font-family: -apple-system, Helvetica, Arial, sans-serif;
              margin: 40px auto; max-width: 900px; color: #222; }
    h1      { margin-bottom: 4px; }
    .sub    { color: #777; margin-bottom: 28px; }
    .summary{ background: #f6f7f9; border-left: 3px solid #888;
              padding: 16px 18px; margin-bottom: 28px; line-height: 1.6;
              white-space: pre-wrap; }
    .boxes  { display: flex; gap: 12px; margin-bottom: 28px; }
    .box    { flex: 1; border: 1px solid #ddd; border-radius: 8px; padding: 14px; }
    .num    { font-size: 28px; font-weight: 600; }
    .label  { color: #777; font-size: 13px; }
    table   { width: 100%; border-collapse: collapse; font-size: 14px; }
    th      { text-align: left; border-bottom: 2px solid #ddd; padding: 8px; }
    td      { border-bottom: 1px solid #eee; padding: 8px; vertical-align: top; }
    .pill   { padding: 2px 8px; border-radius: 10px; font-size: 12px; }
    .high   { background: #fde2e0; color: #8b1a10; }
    .medium { background: #fdf0d5; color: #8a5a00; }
    .low    { background: #e6f0e6; color: #2a5c2a; }
  </style>
</head>
<body>
  <h1>Log Analysis Report</h1>
  <div class="sub">${data.fileName} &middot; ${data.total} lines read</div>

  <div class="summary">${summary}</div>

  <div class="boxes">
    <div class="box"><div class="num">${data.threatCount}</div><div class="label">threats found</div></div>
    <div class="box"><div class="num">${data.severityCount.high}</div><div class="label">high</div></div>
    <div class="box"><div class="num">${data.severityCount.medium}</div><div class="label">medium</div></div>
    <div class="box"><div class="num">${data.severityCount.low}</div><div class="label">low</div></div>
  </div>

  <table>
    <tr><th>Time</th><th>Threat</th><th>Severity</th><th>MITRE</th><th>Log line</th></tr>${rows}
  </table>
</body>
</html>`;

return [{ json: { html: html } }];
